#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// 3D grid layout: i (outer), j (middle), k (inner / contiguous)
	DEFINE_PROTO_STRUCT(grid_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

/* Array initialization. */
void init_array(int n, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j x k
	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		num_t value = (num_t)(i + j + (n - (int)k)) * (num_t)10 / (num_t)n;
		A[state] = value;
		B[state] = value;
	});
}

/* Main computational kernel. The whole function will be timed,
   including the call and return. */
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	const num_t c0_125 = (num_t)0.125;
	const num_t c2_0   = (num_t)2.0;

	// A, B: i x j x k

#pragma scop
	for (int t = 1; t <= tsteps; t++) {
		// First sweep: update B from A on the interior points
		traverser(A, B)
			.order(noarr::slice<'i'>(1, n - 2)
			     ^ noarr::slice<'j'>(1, n - 2)
			     ^ noarr::slice<'k'>(1, n - 2))
			.for_each([=](auto state) {
				// center
				const auto &A_center = A[state];

				// i-neighbors
				auto s_ip1 = noarr::neighbor<'i'>(state, +1);
				auto s_im1 = noarr::neighbor<'i'>(state, -1);

				// j-neighbors
				auto s_jp1 = noarr::neighbor<'j'>(state, +1);
				auto s_jm1 = noarr::neighbor<'j'>(state, -1);

				// k-neighbors
				auto s_kp1 = noarr::neighbor<'k'>(state, +1);
				auto s_km1 = noarr::neighbor<'k'>(state, -1);

				B[state] =
					c0_125 * (A[s_ip1] - c2_0 * A_center + A[s_im1]) +
					c0_125 * (A[s_jp1] - c2_0 * A_center + A[s_jm1]) +
					c0_125 * (A[s_kp1] - c2_0 * A_center + A[s_km1]) +
					A_center;
			});

		// Second sweep: update A from B on the interior points
		traverser(A, B)
			.order(noarr::slice<'i'>(1, n - 2)
			     ^ noarr::slice<'j'>(1, n - 2)
			     ^ noarr::slice<'k'>(1, n - 2))
			.for_each([=](auto state) {
				// center
				const auto &B_center = B[state];

				// i-neighbors
				auto s_ip1 = noarr::neighbor<'i'>(state, +1);
				auto s_im1 = noarr::neighbor<'i'>(state, -1);

				// j-neighbors
				auto s_jp1 = noarr::neighbor<'j'>(state, +1);
				auto s_jm1 = noarr::neighbor<'j'>(state, -1);

				// k-neighbors
				auto s_kp1 = noarr::neighbor<'k'>(state, +1);
				auto s_km1 = noarr::neighbor<'k'>(state, -1);

				A[state] =
					c0_125 * (B[s_ip1] - c2_0 * B_center + B[s_im1]) +
					c0_125 * (B[s_jp1] - c2_0 * B_center + B[s_jm1]) +
					c0_125 * (B[s_kp1] - c2_0 * B_center + B[s_km1]) +
					B_center;
			});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n       = N;
	int tsteps  = TSTEPS;

	// set lengths for all spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n)
	  ^ noarr::set_length<'j'>(n)
	  ^ noarr::set_length<'k'>(n);

	// allocate data (bags own their memory)
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);

	// initialize arrays
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, SCALAR_VAL, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (N, TSTEPS, ...)
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A and B are 3D: A[i][j][k], B[i][j][k]
	// C row-major layout: k is fastest, then j, then i
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// Array initialization.
// A[i][j][k] = B[i][j][k] = (i + j + (n - k)) * 10 / n
void init_array(int n, auto A, auto B) {
	using namespace noarr;

	const std::size_t nn = static_cast<std::size_t>(n);

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		num_t value =
			static_cast<num_t>(i + j + (nn - k)) *
			static_cast<num_t>(10) /
			static_cast<num_t>(nn);

		A[state] = value;
		B[state] = value;
	});
}

// Main computational kernel.
// Time-stepping 3D heat stencil.
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(std::size_t tsteps, auto A, auto B) {
	using namespace noarr;

	// All spatial sizes are taken from the structure.
	const std::size_t ni = A | get_length<'i'>();
	const std::size_t nj = A | get_length<'j'>();
	const std::size_t nk = A | get_length<'k'>();

	// Traverse only interior points: i, j, k in [1, n-2]
	auto interior =
		slice<'i'>(1u, ni - 2u) ^
		slice<'j'>(1u, nj - 2u) ^
		slice<'k'>(1u, nk - 2u);

	#pragma scop
	for (std::size_t t = 0; t < tsteps; t++) {

		// B <- stencil(A)
		traverser(B, A).order(interior).for_each([=](auto state) {
			const num_t center = A[state];

			B[state] =
				SCALAR_VAL(0.125) *
					(A[state + idx<'i'>(1)] - SCALAR_VAL(2.0) * center + A[state - idx<'i'>(1)]) +
				SCALAR_VAL(0.125) *
					(A[state + idx<'j'>(1)] - SCALAR_VAL(2.0) * center + A[state - idx<'j'>(1)]) +
				SCALAR_VAL(0.125) *
					(A[state + idx<'k'>(1)] - SCALAR_VAL(2.0) * center + A[state - idx<'k'>(1)]) +
				center;
		});

		// A <- stencil(B)
		traverser(A, B).order(interior).for_each([=](auto state) {
			const num_t center = B[state];

			A[state] =
				SCALAR_VAL(0.125) *
					(B[state + idx<'i'>(1)] - SCALAR_VAL(2.0) * center + B[state - idx<'i'>(1)]) +
				SCALAR_VAL(0.125) *
					(B[state + idx<'j'>(1)] - SCALAR_VAL(2.0) * center + B[state - idx<'j'>(1)]) +
				SCALAR_VAL(0.125) *
					(B[state + idx<'k'>(1)] - SCALAR_VAL(2.0) * center + B[state - idx<'k'>(1)]) +
				center;
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n      = N;
	std::size_t tsteps = TSTEPS;

	// set lengths for all spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate data (owning bags)
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(static_cast<int>(n), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, A.get_ref(), B.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print resulting array (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Hoist 'i' for a predictable outer dimension in the serialized output
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

