#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A[i][j][k] and B[i][j][k], with k the innermost (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// Array initialization: matches the original init_array
// A[i][j][k] = B[i][j][k] = (i + j + (n - k)) * 10 / n;
void init_array(auto A, auto B) {
	using namespace noarr;

	auto n = A | get_length<'i'>();
	num_t n_val = (num_t)n;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		num_t val = (num_t)(i + j + (n - k)) * (num_t)10.0 / n_val;

		A[state] = val;
		B[state] = val;
	});
}

// Main computational kernel
// Corresponds to the original kernel_heat_3d
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, auto A, auto B) {
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Restrict iteration to interior points: i,j,k in [1, n-2]
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	const num_t coef = (num_t)0.125;
	const num_t two  = (num_t)2.0;

#pragma scop
	for (int t = 1; t <= tsteps; t++) {
		// First phase: update B from A
		noarr::traverser(A, B).order(interior).for_each([=](auto state) {
			// state has i,j,k with 1 <= i,j,k <= n-2
			num_t center = A[state];

			num_t xp = A[state + noarr::idx<'i'>(1)];
			num_t xm = A[state - noarr::idx<'i'>(1)];

			num_t yp = A[state + noarr::idx<'j'>(1)];
			num_t ym = A[state - noarr::idx<'j'>(1)];

			num_t zp = A[state + noarr::idx<'k'>(1)];
			num_t zm = A[state - noarr::idx<'k'>(1)];

			B[state] =
				  coef * (xp - two * center + xm)
				+ coef * (yp - two * center + ym)
				+ coef * (zp - two * center + zm)
				+ center;
		});

		// Second phase: update A from B
		noarr::traverser(A, B).order(interior).for_each([=](auto state) {
			num_t center = B[state];

			num_t xp = B[state + noarr::idx<'i'>(1)];
			num_t xm = B[state - noarr::idx<'i'>(1)];

			num_t yp = B[state + noarr::idx<'j'>(1)];
			num_t ym = B[state - noarr::idx<'j'>(1)];

			num_t zp = B[state + noarr::idx<'k'>(1)];
			num_t zm = B[state - noarr::idx<'k'>(1)];

			A[state] =
				  coef * (xp - two * center + xm)
				+ coef * (yp - two * center + ym)
				+ coef * (zp - two * center + zm)
				+ center;
		});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// Common length proto-structure for all spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// Allocate data (bags own their memory)
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// Initialize arrays
	init_array(A.get_ref(), B.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_heat_3d(tsteps, A.get_ref(), B.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print result (to keep the data live and allow checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Hoist i and j for a more regular output order
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>() ^ noarr::hoist<'j'>());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
